import type { ComboboxProps } from "./combobox.types";
import type { CSSObject } from "@emotion/react";

import { IconButtonClasses } from "@components/icon-button";
import styled from "@emotion/styled";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import { useMemo } from "react";

const componentName = "Combobox";

export const ComboboxClasses = {
  root: "exp-textura_combobox",
  sm: "exp-textura_combobox_sm",
  input: "exp-textura_combobox_input",
  content: "exp-textura_combobox_content",
  itemsWrapper: "exp-textura_combobox_items_wrapper",
  item: "exp-textura_combobox_item",
  prefix: "exp-textura_combobox_prefix",
  suffix: "exp-textura_combobox_suffix",
  itemActive: "exp-textura_combobox_item_active",
  itemSelected: "exp-textura_combobox_item_selected",
  button: "exp-textura_combobox_button",
  group: "exp-textura_combobox_group",
  groupLabel: "exp-textura_combobox_group_label",
  divider: "exp-textura_combobox_divider",
  clearIconButton: "exp-textura_combobox_clear_icon_button",
  noResults: "exp-textura_combobox_no_results",
};

// Set up style variant settings for the component (if more than "default"), using style slots
// const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
//   exampleVariant: { root: { backgroundColor: theme.color.background.default } },
// });

const generateStyles = (props: ComboboxProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<ComboboxProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        // getVariantConfig(theme),
      ),
    [theme, variant, styleSlotsProp],
  );

  // Return the JSS generated from the variant settings, make sure to include style slots
  return {
    position: "relative",
    display: "inline-block",
    width: "100%",

    [`&.${ComboboxClasses.sm}`]: {
      ...styleSlots?.sm,
    },

    [`.${ComboboxClasses.input}`]: {
      ...styleSlots?.input,
    },

    [`.${ComboboxClasses.itemsWrapper}`]: {
      ...styleSlots?.itemsWrapper,
    },

    [`&.${ComboboxClasses.content}`]: {
      margin: 0,
      listStyle: "none",
      overflowY: "auto",
      maxHeight: "100vh",
      backgroundColor: theme.color.background.default,
      border: `${theme.toRem(theme.border.width.sm)} solid ${theme.color.border.default}`,
      borderRadius: theme.toRem(theme.border.radius.sm),
      boxShadow: theme.dropShadow.lg,
      color: theme.color.content.default,
      ...theme.typography.body.md,
      minWidth: theme.toRem(260),
      zIndex: theme.zIndex.dynamic,
      "&:focus-visible": {
        boxShadow: theme.dropShadow.lg,
      },
      ...styleSlots?.content,
    },

    [`.${ComboboxClasses.item}`]: {
      boxSizing: "border-box",
      display: "flex",
      alignItems: "center",
      width: "100%",
      userSelect: "none",
      textDecoration: "none",
      borderRadius: theme.toRem(theme.border.radius.sm),
      ...theme.typography.body.md,
      gap: theme.toRem(theme.spacing[8]),
      color: theme.menu.default.color.content.enabled,
      position: "relative",
      cursor: "pointer",
      minHeight: theme.toRem(32),
      padding: `${theme.toRem(theme.spacing[4])} ${theme.toRem(theme.spacing[8])}`,
      "&:focus-visible": {
        boxShadow: "none",
      },
      "&[data-disabled]": {
        color: theme.menu.default.color.content.disabled,
        pointerEvents: "none",
        ...styleSlots?.itemDisabled,
      },
      [`.${IconButtonClasses.sm}`]: {
        color: theme.color.content.iconWeak,
        ...styleSlots?.itemIconButtonSm,
      },
      ...styleSlots?.item,
    },

    [`.${ComboboxClasses.itemActive}`]: {
      backgroundColor: theme.menu.default.color.background.hover,
      color: theme.menu.default.color.content.hover,
      textDecoration: "none",
      outline: "none",
      boxShadow: "none",
      "&:hover": {
        textDecoration: "none",
        color: theme.menu.default.color.content.hover,
      },
      ...styleSlots?.itemHighlighted,
    },

    [`.${ComboboxClasses.itemSelected}`]: {
      ...styleSlots?.itemSelected,
    },

    [`.${ComboboxClasses.prefix}`]: {
      ...styleSlots?.prefix,
    },

    [`.${ComboboxClasses.suffix}`]: {
      ...styleSlots?.suffix,
    },

    [`.${ComboboxClasses.button}`]: {
      all: "unset",
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      color: theme.color.content.default,
      cursor: "pointer",
      "&[disabled]": {
        cursor: "not-allowed",
        color: theme.inputDropdown.default.color.content.disabled,
      },
      ...styleSlots?.button,
    },

    [`.${ComboboxClasses.group}`]: {
      display: "flex",
      flexDirection: "column",
      gap: theme.toRem(theme.spacing[4]),
      padding: theme.toRem(theme.spacing[8]),
      ...styleSlots?.group,
    },

    [`.${ComboboxClasses.groupLabel}`]: {
      display: "flex",
      alignItems: "baseline",
      color: theme.color.content.weak,
      padding: `${theme.toRem(theme.spacing[8])} ${theme.toRem(theme.spacing[8])} 0 ${theme.toRem(
        theme.spacing[8],
      )}`,
      ...theme.typography.label.sm,
      ...styleSlots?.groupLabel,
    },

    [`.${ComboboxClasses.divider}`]: {
      height: theme.toRem(theme.border.width.sm),
      backgroundColor: theme.color.border.default,
      ...styleSlots?.divider,
    },

    [`.${ComboboxClasses.clearIconButton}`]: {
      ...styleSlots?.clearIconButton,
    },

    [`.${ComboboxClasses.noResults}`]: {
      display: "flex",
      alignItems: "center",
      justifyContent: "flex-start",
      color: theme.color.content.weak,
      padding: `${theme.toRem(theme.spacing[40])} ${theme.toRem(theme.spacing[16])}`,
      ...theme.typography.body.md,
      ...styleSlots?.noResults,
    },

    ...styleSlots?.root,
  };
};

const excludedDOMProps = getExcludedDOMProps();

export const StyledCombobox = styled("div", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<ComboboxProps>((props) => generateStyles(props));
